window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"DXHHyPaKNwI","speaker":"Dhananjay Ramful","role":"Foreign Minister","country":"Mauritius","region":"Africa","url":"https://www.youtube.com/watch?v=DXHHyPaKNwI","date":"20260926","title":"🇲🇷 Mauritius - Foreign Minister Addresses United Nations General Assembly 81st Session | #UNGA","seconds":1135,"words":2227,"counts":{"claims":29,"promises":0,"attacks":0},"topics":[{"topic":"Mauritius territorial dispute","share":0.1292,"seconds":147},{"topic":"UN institutional reform","share":0.1234,"seconds":140},{"topic":"UN Security Council","share":0.0793,"seconds":90},{"topic":"Climate change law","share":0.0705,"seconds":80},{"topic":"Mauritius technology","share":0.0656,"seconds":74},{"topic":"Development finance","share":0.0647,"seconds":73},{"topic":"Climate change impacts","share":0.0618,"seconds":70},{"topic":"UN institutional history","share":0.0616,"seconds":70},{"topic":"Mauritius public health","share":0.0601,"seconds":68},{"topic":"Health emergency funding","share":0.0591,"seconds":67},{"topic":"Middle East conflict","share":0.059,"seconds":67},{"topic":"UNGA leadership","share":0.0566,"seconds":64},{"topic":"Ocean governance","share":0.0559,"seconds":64},{"topic":"Human rights discrimination","share":0.0532,"seconds":60}],"timeline":[[2,66,"UNGA leadership"],[68,138,"UN institutional history"],[139,209,"UN institutional reform"],[210,300,"UN Security Council"],[301,381,"Climate change law"],[382,452,"Climate change impacts"],[453,527,"Development finance"],[528,602,"Mauritius technology"],[604,667,"Ocean governance"],[668,729,"Human rights discrimination"],[730,797,"Middle East conflict"],[799,883,"Mauritius territorial dispute"],[884,947,"Mauritius territorial dispute"],[948,1016,"Mauritius public health"],[1017,1084,"Health emergency funding"],[1086,1157,"UN institutional reform"],[1158,1172,null]],"stances":{"UNGA leadership":"Dhananjay Ramful congratulates the newly elected President and expresses support for him.","UN institutional history":"Dhananjay Ramful describes the UN's eight-decade evolution from a focus on peace and security to a broader scope including decolonization, development, and human rights.","UN institutional reform":"Dhananjay Ramful argues that the UN must be adapted for the 21st century to ensure developing countries are not excluded from international rule-making and financial architecture.","UN Security Council":"Dhananjay Ramful calls for accelerating the revitalization of the General Assembly and ECOSOC while supporting specific reforms to the Security Council, including African representation under the Ezulwini consensus, seats for SIDS, restrictions on veto power, and alignment with the G4.","Climate change law":"Dhananjay Ramful supports the ICJ's advisory opinion on climate change obligations and calls for its full operationalization.","Climate change impacts":"Dhananjay Ramful supports the ICJ legal principle that states are not obligated to update maritime baselines due to sea level rise and calls for formal codification of statehood sovereignty protection, while urging urgent global action on water and climate finance.","Development finance":"Dhananjay Ramful argues that concessional financing for developing countries is declining when needed most and calls for a review of access criteria to reflect vulnerability rather than just income per capita.","Mauritius technology":"Dhananjay Ramful states that digital innovation is a developmental imperative for Mauritius and highlights the country's national strategies supported by the UN.","Ocean governance":"Dhananjay Ramful welcomes the ratification of the BBNJ agreement and calls for its prompt implementation while highlighting the importance of international collaboration for maritime security.","Human rights discrimination":"Dhananjay Ramful states that Mauritius attaches great importance to eliminating racism and reaffirms commitment to the international decade for people of African descent.","Middle East conflict":"Dhananjay Ramful states that the crisis in the Gulf and threats to navigation have sent shockwaves across the global economy, affecting small open economies like Mauritius which depend on maritime trade routes for energy and food.","Mauritius territorial dispute":"Dhananjay Ramful asserts that the agreement on the Chagos Archipelago signed in May 2025 proves that multilateralism and UN judicial organs can achieve peaceful dispute settlement and decolonization, while calling for states to respect international law and correct historical injustices.","Mauritius public health":"Dhananjay Ramful states that Mauritius is strengthening its public health system through investment and service improvements to ensure free care for all citizens, while supporting global efforts on universal health coverage and pandemic preparedness.","Health emergency funding":"Dhananjay Ramful argues that pandemic financing eligibility must be expanded to include a vulnerability index and calls for increased international attention and resources for road safety."},"claims":[{"t":80,"quote":"the United Nations has now completed the first eight decades of its existence. Eight decades replete with resolutions, declarations, and action on decolonization, development, new international order, the new constitution for the oceans, as well as climate and environment, technology, human rights, international law","topic":"UN institutional history","kind":"fact"},{"t":108,"quote":"Created in the aftermath of the Second World War, the immediate focus was obviously on peace and security.","topic":"UN institutional history","kind":"fact"},{"t":189,"quote":"We all acknowledge that the three pillars of the UN charter are peace and security, development, and human rights.","topic":"UN institutional reform","kind":"fact"},{"t":198,"quote":"The twin institutional pillars provided in the charter were and still are the Security Council and ECOSOC as the apex bodies for achieving these purposes.","topic":"UN institutional reform","kind":"fact"},{"t":236,"quote":"The historical injustice regarding the composition of the Council was acknowledged in action 39 of the pact for the future.","topic":"UN Security Council","kind":"fact"},{"t":249,"quote":"Mauritius fully supports the common African position, the Ezulwini consensus, and the Serti calling for no fewer than two permanent and five non-permanent African seats on the Council.","topic":"UN Security Council","kind":"fact"},{"t":338,"quote":"We welcome the landmark unanimous advisory opinion of the ICJ on the obligations of states in respect of climate change.","topic":"Climate change law","kind":"fact"},{"t":346,"quote":"This was a vindication of the tireless advocacy of Vanuatu and the core group of states.","topic":"Climate change law","kind":"fact"},{"t":382,"quote":"We also support the legal principle affirmed by the ICJ that states are under no obligation to update their maritime baselines or zones to account for climate-induced sea level rise.","topic":"Climate change impacts","kind":"fact"},{"t":415,"quote":"Mauritius welcomes the holding of the UN Water Conference in December this year.","topic":"Climate change impacts","kind":"fact"},{"t":459,"quote":"Concessional financing for developing countries is declining precisely when the need is greatest.","topic":"Development finance","kind":"fact"},{"t":467,"quote":"The graduation of countries, including small island developing states, should be encouraged and supported, and not prejudice access to affordable finance.","topic":"Development finance","kind":"fact"},{"t":533,"quote":"We have with UN support, a national artificial intelligence strategy, and a national fintech strategy.","topic":"Mauritius technology","kind":"fact"},{"t":557,"quote":"As a coastal state with an EEZ of 2.2 million square kilometers, that is more than 1,000 times our landmass","topic":"Mauritius technology","kind":"number"},{"t":585,"quote":"We welcome the decisions of the UN Commission on the limits of the continental shelf approving the submission lodged by Mauritius in 2008 and approved in March 2011, as well as the second one filed in May 2009 and approved in July 2026.","topic":"Mauritius technology","kind":"fact"},{"t":604,"quote":"We welcome the 100th ratification of the BBNJ agreement and calls for its prompt and effective implementation.","topic":"Ocean governance","kind":"fact"},{"t":639,"quote":"I am pleased to inform that Mauritius will, with the support of the European Union and the Commission de l'Océan Indien, will host a ministerial conference on cybercrime and sea cable security in the western Indian Ocean in the first quarter of Mr. President, Mauritius welcomes the major developments taking place across Africa with regards to greater integration and pooling of resources, particularly in relation to capacity building.","topic":"Ocean governance","kind":"self_credit"},{"t":670,"quote":"Mauritius has initiated action at the UN for promoting enhanced regulatory frameworks in developing countries, namely through pooling of resources.","topic":"Human rights discrimination","kind":"fact"},{"t":711,"quote":"Earlier this year, Mauritius adopted new legislation to further enhance the protection of women's rights.","topic":"Human rights discrimination","kind":"fact"},{"t":743,"quote":"which depends on maritime trade routes for over 90% of its primary energy imports and more than 70% of its food supply","topic":"Middle East conflict","kind":"number"},{"t":810,"quote":"The agreement on the Chagos Archipelago signed by Mauritius and the United Kingdom in May 2025 stands as living proof that trust in multilateralism and UN judicial organs can achieve the peaceful settlement of disputes and the completion of our nation's decolonization and restore the rights of Mauritians of Chagos origin by force of law.","topic":"Mauritius territorial dispute","kind":"fact"},{"t":840,"quote":"Trust, specially amongst neighbors and in the region, is reinforced when there is respect for the rule of law, for the resolutions of the United Nations General Assembly, the ruling of the International Tribunal on the law of the sea, and the ICJ's advisory opinion on the Chagos Archipelago, which carries","topic":"Mauritius territorial dispute","kind":"fact"},{"t":903,"quote":"Trou aux Biches Islands is an integral part of the territory of the Republic of We have constantly maintained our position concerning the sovereignty of the Republic of Mauritius over this","topic":"Mauritius territorial dispute","kind":"fact"},{"t":934,"quote":"Mauritius is committed to upholding the pledges made at the social summit in Doha last year. Nowhere is that promise to universal social protection more concrete than in our health services.","topic":"Mauritius territorial dispute","kind":"fact"},{"t":948,"quote":"As non-communicable diseases and a rapidly aging population place growing pressure on our health system, we are strengthening public health care through major investment, improved service delivery, expanded specialized care, and a greater focus on Mauritius will continue to offer free and quality public health care to each and every citizen.","topic":"Mauritius public health","kind":"fact"},{"t":987,"quote":"Today, the high-level meeting on pandemic prevention, preparedness, and response met at a decisive moment.","topic":"Mauritius public health","kind":"fact"},{"t":1017,"quote":"It is of crucial importance to widen pandemic financing eligibility, including the pandemic fund, to formally incorporate the vulnerability index.","topic":"Health emergency funding","kind":"fact"},{"t":1035,"quote":"an issue to which we attach the highest importance and which acts as a silent epidemic that continues to claim far too many lives disproportionately in developing countries.","topic":"Health emergency funding","kind":"fact"},{"t":1113,"quote":"The fact that the number of actors has more than tripled in the past eight reflects an engagement that and a commitment that is even bigger and even more diverse than it was when the UN was We are confident that the international around half of which is made up of young people that aim to protect the planet, that want to better share wealth, and aspire to use new technologies advisedly, will be able to overcome new","topic":"UN institutional reform","kind":"fact"}],"promises":[],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":"UNGA leadership","text":"And I'll give the floor to His Ramful, Minister of Foreign Affairs, Regional Integration, and International Trade of Mauritius. &gt;&gt; Mr. President, allow me to congratulate His Excellency Dr. Kalihur Rahman on his election to the presidency of the General Assembly and assure him of the support of my I also wish to pay tribute to His Antonio Guterres for his outstanding dedication and commitment to this organization during his two terms as Secretary-General."},{"t":68,"topic":"UN institutional history","text":"He will be remembered as a leader with a steady hand, always guided by principles of fairness, compassion, and dignity for Mr. President, the United Nations has now completed the first eight decades of its existence. Eight decades replete with resolutions, declarations, and action on decolonization, development, new international order, the new constitution for the oceans, as well as climate and environment, technology, human rights, international law, and Created in the aftermath of the Second World War, the immediate focus was obviously on peace and security. But the UN system has evolved significantly over the decades to expand its scope and sphere of influence within the confines of its charter. the UN must now look to the future building on its record of achievements as well as from lessons learned from what it could not achieve."},{"t":139,"topic":"UN institutional reform","text":"As we look to the next 80 years, we must ask ourselves a searching question. Is the UN fit for the purpose for the 21st century? Not the world of 1945, but the world of today and beyond. We are entering a new era of international relations defined by unprecedented technological Often absent from the table where the rules of tomorrow are being adopted, developing countries risk being left further behind. The same exclusion afflicts the international financial architecture, which remains skewed against the global Developing nations must have a seat at the table as equal stakeholders. We all acknowledge that the three pillars of the UN charter are peace and security, development, and human rights. The twin institutional pillars provided in the charter were and still are the Security Council and ECOSOC as the apex bodies for achieving these purposes."},{"t":210,"topic":"UN Security Council","text":"However, over the years optimal use has been made primarily of only one of these organs. We need to enhance and accelerate the revitalization of the General Assembly and that of ECOSOC so that they are not merely forums for debate, but engines of This must be done as we bring about the reform of the Security Council. The historical injustice regarding the composition of the Council was acknowledged in action 39 of the pact for the future. But the process for reform is still Mauritius fully supports the common African position, the Ezulwini consensus, and the Serti calling for no fewer than two permanent and five non-permanent African seats on the Council. Mauritius also supports the call for SIDS to have a seat on a reformed On the question of the veto, Mauritius aligns itself with the position of a growing number of states that in the event the veto is retained, any new permanent member must have the same rights as the original permanent Mauritius also supports the Franco-Mexican initiative on the suspension of the veto in cases of mass We support the positions of the G4"},{"t":301,"topic":"Climate change law","text":"and L69 on Council reform, and we reiterate our support for India's candidature for a permanent seat commensurate with its constructive role in global affairs. Mr. President, Mauritius welcomes the increasing recourse to the International Court of Justice as a mechanism for the peaceful settlement of disputes and determination of issues of international law. We call upon member states which have not yet done so to accept the compulsory jurisdiction of the ICJ. We welcome the landmark unanimous advisory opinion of the ICJ on the obligations of states in respect of climate change. This was a vindication of the tireless advocacy of Vanuatu and the core group of states. Mauritius was proud to stand among them. We call for the full operationalization of this advisory opinion, including through the follow-up action requested by this assembly, in accordance with the UN General Assembly landmark resolution of the 20th of May 2026, welcoming the advisory opinion of the International Court of Justice on the obligations of states in respect of climate change."},{"t":382,"topic":"Climate change impacts","text":"We also support the legal principle affirmed by the ICJ that states are under no obligation to update their maritime baselines or zones to account for climate-induced sea level rise. Mauritius calls for the principle that statehood and sovereignty are not impacted by sea level rise to be formally codified. Mr. President, water stands at the frontline of the climate crisis. Water is a major concern globally, and Mauritius welcomes the holding of the UN Water Conference in December this year. We look forward to this crucial global issue being addressed by the international committee community as a matter of urgency. We also call for enhanced, accessible, and predictable climate finance, accompanied by comprehensive capacity building and disaster risk management for the most I also wish to highlight that Mauritius is currently conducting a constitutional review exercise, which will include giving constitutional protection to the rights of nature."},{"t":453,"topic":"Development finance","text":"Mr. President, the crisis in development financing is Concessional financing for developing countries is declining precisely when the need is greatest. The graduation of countries, including small island developing states, should be encouraged and supported, and not prejudice access to affordable finance. Mauritius calls for a review of the criteria for access to concessional financing that reflect vulnerability rather than income per capita alone. We also call for the strengthening of the rules-based multilateral trading system, and for fair, transparent, and equitable mechanisms for resolving trade disputes. Mr. President, the rapid evolution of digital and emerging technologies, including artificial intelligence, is already shaping economic, social, and institutional developments across the We support the General Assembly resolution establishing the global dialogue on AI governance, and welcome the work being done by the independent international scientific panel on AI."},{"t":528,"topic":"Mauritius technology","text":"For Mauritius, digital innovation is a developmental imperative. We have with UN support, a national artificial intelligence strategy, and a national fintech strategy. We need an open, transparent, and inclusive dialogue on governance of the new technologies, which ensures that the benefits of technological progress are shared equitably, and that the risks are managed collectively. As a coastal state with an EEZ of 2.2 million square kilometers, that is more than 1,000 times our landmass, Mauritius is profoundly connected to the We affirm our unwavering commitment to UNCLOS as the legal framework governing all activities in the oceans, including the seabed and subsoil beyond national We welcome the decisions of the UN Commission on the limits of the continental shelf approving the submission lodged by Mauritius in 2008 and approved in March 2011, as well as the second one filed in May 2009 and approved in July 2026."},{"t":604,"topic":"Ocean governance","text":"We welcome the 100th ratification of the BBNJ agreement and calls for its prompt and effective implementation. We look to its first conference of the parties advancing the institutional, financial, and procedural arrangement necessary for the effective implementation of the Collaboration is key to effective maritime security, maritime surveillance, and domain awareness. We call on the international community to support regional and subregional initiatives in this regard. I am pleased to inform that Mauritius will, with the support of the European Union and the Commission de l'Océan Indien, will host a ministerial conference on cybercrime and sea cable security in the western Indian Ocean in the first quarter of Mr. President, Mauritius welcomes the major developments taking place across Africa with regards to greater integration and pooling of resources, particularly in relation to capacity building."},{"t":668,"topic":"Human rights discrimination","text":"In this regard, Mauritius has initiated action at the UN for promoting enhanced regulatory frameworks in developing countries, namely through pooling of resources. Mauritius attaches great importance to the elimination of all forms of racism, racial discrimination, and xenophobia. We welcome the high-level meeting on this subject and reaffirm our commitment to the international decade for people of African descent. Mauritius is fully committed to supporting the convention on the elimination of all forms of discrimination against women and the Beijing Declaration and Platform for Earlier this year, Mauritius adopted new legislation to further enhance the protection of women's rights. Mr. President, we are deeply concerned by the effects of regional conflicts and instability on development, economic growth, food security, and the achievement of SDGs."},{"t":730,"topic":"Middle East conflict","text":"The crisis in the Gulf and threats to freedom of navigation have sent shockwaves across the global economy. For a small, open economy such as Mauritius, which depends on maritime trade routes for over 90% of its primary energy imports and more than 70% of its food supply, these effects are felt acutely. We call for restraint, for dialogue, and for a durable diplomatic resolution. On Palestine, Mauritius reaffirms its long-standing position in support of the inalienable right of the Palestinian people to self-determination and to an independent sovereign state with East Jerusalem as its capital, living in peace and security along its neighbors. The cycle of violence must end. Too many people have suffered for far too long. We note with deep concern that the establishment of unlawful settlements may be a major obstacle to peace."},{"t":799,"topic":"Mauritius territorial dispute","text":"Mr. President, I now come to an issue which for Mauritius is non-negotiable. It concerns our sovereignty over the Chagos Islands. The agreement on the Chagos Archipelago signed by Mauritius and the United Kingdom in May 2025 stands as living proof that trust in multilateralism and UN judicial organs can achieve the peaceful settlement of disputes and the completion of our nation's decolonization and restore the rights of Mauritians of Chagos origin by force of law. Trust, specially amongst neighbors and in the region, is reinforced when there is respect for the rule of law, for the resolutions of the United Nations General Assembly, the ruling of the International Tribunal on the law of the sea, and the ICJ's advisory opinion on the Chagos Archipelago, which carries We trust that states which laid the very foundation of the new post-war legal will recommit to full respect and compliance with international law and correct this historical injustice without delay."},{"t":884,"topic":"Mauritius territorial dispute","text":"As William Ewart Gladstone, a four-term former prime British Prime Minister and great campaigner for peace and freedom, put it, \"Justice delayed is justice denied.\" Monsieur le Président, &gt;&gt; Mr. President, Trou aux Biches Islands is an integral part of the territory of the Republic of We have constantly maintained our position concerning the sovereignty of the Republic of Mauritius over this We reiterate our call upon France to engage constructively with a view to resolving the dispute relating to Tromelin Island in the spirit of friendship which characterizes relations between our two &gt;&gt; Mr. President, Mauritius is committed to upholding the pledges made at the social summit in Doha last year. Nowhere is that promise to universal social protection more concrete than in our health services."},{"t":948,"topic":"Mauritius public health","text":"As non-communicable diseases and a rapidly aging population place growing pressure on our health system, we are strengthening public health care through major investment, improved service delivery, expanded specialized care, and a greater focus on Mauritius will continue to offer free and quality public health care to each and every citizen. We thus welcome the holding of the 2027 high-level meeting on universal health coverage, and Mauritius stands ready to contribute to that global effort. Today, the high-level meeting on pandemic prevention, preparedness, and response met at a decisive moment. And decisive moments demand more than mere intentions. Mauritius supports the conclusions of the terms of benefit-sharing guaranteeing vulnerable countries real access to affordable, safe, effective, and quality medicines, including generics, vaccines, uh diagnosis, diagnostics, and health technologies."},{"t":1017,"topic":"Health emergency funding","text":"It is of crucial importance to widen pandemic financing eligibility, including the pandemic fund, to formally incorporate the vulnerability index. Mauritius also welcomes UN initiatives on roof on road safety, an issue to which we attach the highest importance and which acts as a silent epidemic that continues to claim far too many lives disproportionately in developing countries. We call for greater international attention and resources for this critical issue. &gt;&gt; Mr. President, we find ourselves at a critical juncture in the history of the United Nations. The organization is facing significant challenges both internally and Internally, there is the process launched by the Secretary-General to update the administrative and financial structure of the organization to allow our organization to be better equipped to overcome future challenges."},{"t":1086,"topic":"UN institutional reform","text":"Externally, the role and the functions of the organization, as well as the composition of its principal organs, are in doubt and need to be redefined. The voluntary the will expressed by the international community following the war to create an instrument for cooperation in order to establish a new world order is still there. The fact that the number of actors has more than tripled in the past eight reflects an engagement that and a commitment that is even bigger and even more diverse than it was when the UN was We are confident that the international around half of which is made up of young people that aim to protect the planet, that want to better share wealth, and aspire to use new technologies advisedly, will be able to overcome new We reiterate our commitment to as well as our confidence in its ability to respond to people's expectations."},{"t":1158,"topic":null,"text":"Thank you, Mr. President. &gt;&gt; I thank the Minister of Foreign Affairs, Regional Integration and International Trade of Mauritius."}],"compare":[{"topic":"UN & its reform","share":0.2763,"mean":0.2044,"rank":54,"others":170},{"topic":"Climate Change","share":0.141,"mean":0.0423,"rank":18,"others":77},{"topic":"Mauritius","share":0.1377,"mean":0.0,"rank":1,"others":0},{"topic":"Global Economy","share":0.0689,"mean":0.0143,"rank":21,"others":31},{"topic":"Global Health","share":0.063,"mean":0.0021,"rank":3,"others":6},{"topic":"Middle East","share":0.0628,"mean":0.007,"rank":9,"others":19},{"topic":"Ocean Governance","share":0.0596,"mean":0.0065,"rank":11,"others":16},{"topic":"Human Rights","share":0.0567,"mean":0.0083,"rank":10,"others":24}]};
